module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg  [5:0] y;
    reg        w;
    wire       Y1;
    wire       Y3;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    integer errors = 0;
    integer i;

    // Task to check outputs against expected values
    task check_outputs;
        input [5:0] exp_y;
        input       exp_w;
        input       exp_Y1;
        input       exp_Y3;
        begin
            y = exp_y;
            w = exp_w;
            #5; // Wait for combinatorial propagation
            if (Y1 !== exp_Y1) begin
                $display("ERROR: y=%b, w=%b -> Expected Y1=%b, Got Y1=%b", y, w, exp_Y1, Y1);
                errors = errors + 1;
            end
            if (Y3 !== exp_Y3) begin
                $display("ERROR: y=%b, w=%b -> Expected Y3=%b, Got Y3=%b", y, w, exp_Y3, Y3);
                errors = errors + 1;
            end
        end
    endtask

    // 3. Stimulus & self-checking
    initial begin
        // Initialize inputs
        y = 6'b000000;
        w = 1'b0;
        #10;

        // Test state A (y[0] = 6'b000001)
        // A --0--> A (Y1=0, Y3=0)
        check_outputs(6'b000001, 1'b0, 1'b0, 1'b0);
        // A --1--> B (Y1=1, Y3=0)
        check_outputs(6'b000001, 1'b1, 1'b1, 1'b0);

        // Test state B (y[1] = 6'b000010)
